    recipeIngredients: [
      { name: 'Hot Brown', quantity: 'custom (g)', foodWord: 'HOTBROWN', portionDesc: 'custom (g)', portionGrams: 100.0, isDish: true },
      { name: 'salted butter', quantity: '1 tbsp', section: 'cheese_sauce', ndbNo: '1001', portionDesc: 'g', portionGrams: 14.2 },
      { name: 'all-purpose enriched unbleached white flour', quantity: '1 tbsp', section: 'cheese_sauce', ndbNo: '20581', portionDesc: 'g', portionGrams: 8.0 },
      { name: 'heavy cream', quantity: '½ cup', section: 'cheese_sauce', ndbNo: '1053', portionDesc: 'g', portionGrams: 119.0 },
      { name: 'salt', quantity: 'pinch', section: 'cheese_sauce', ndbNo: '2047', portionDesc: 'g', portionGrams: 0.3 },
      { name: 'ground black pepper', quantity: 'pinch', section: 'cheese_sauce', ndbNo: '2030', portionDesc: 'g', portionGrams: 0.2 },
      { name: 'paprika', quantity: 'pinch', section: 'cheese_sauce', ndbNo: '2028', portionDesc: 'g', portionGrams: 0.3 },
      { name: 'Parmesan cheese', quantity: '¼ cup', section: 'cheese_sauce', ndbNo: '1033', portionDesc: 'g', portionGrams: 25.0 },
      { name: 'white bread', quantity: '2 slices (30g each)', section: 'assembly', ndbNo: '18069', portionDesc: 'g', portionGrams: 60.0 },
      { name: 'deli turkey breast', quantity: '4 oz', section: 'assembly', ndbNo: '7081', portionDesc: 'g', portionGrams: 113.4 },
      { name: 'tomato', quantity: '4 thin slices (60g)', section: 'assembly', ndbNo: '11529', portionDesc: 'g', portionGrams: 60.0 },
      { name: 'Parmesan cheese', quantity: '1 tbsp', section: 'assembly', ndbNo: '1033', portionDesc: 'g', portionGrams: 5.0 },
      { name: 'bacon', quantity: '2 strips', section: 'bacon', ndbNo: '10862', portionDesc: 'g', portionGrams: 23.0 }
    ],
    recipeInstructions: [
      'Melt butter in a small saucepan over medium heat, whisk in flour, and cook 1 minute or until lightly brown. Gradually whisk in heavy cream and cook, stirring constantly, until thickened, about 3–4 minutes. Remove from heat, stir in parmesan, and season with salt, pepper, and paprika.',
      'Toast the bread slices and arrange them open-faced side by side in a broiler-safe baking dish.',
      'Top evenly with the sliced turkey, tomato slices and cheese sauce. Sprinkle with the remaining 1 tablespoon of parmesan.',
      'Broil 3–4 minutes until the sauce is bubbling and parmesan lightly browned on top.',
      'Remove from the oven and transfer to serving plate. Cross two bacon strips over the top of each slice and serve immediately.',
      'Suggestions (not included): Serve with a simple green salad or fresh fruit on the side.'
    ],
