      { name: 'ground cumin', quantity: '1 tsp', section: 'falafel', ndbNo: '2014', portionDesc: 'g', portionGrams: 2.0 },
      { name: 'ground coriander', quantity: '1 tsp ground coriander', section: 'falafel', ndbNo: '2013', portionDesc: 'g', portionGrams: 2.0 },
      { name: 'salt', quantity: '¼ tsp', section: 'falafel', ndbNo: '2047', portionDesc: 'g', portionGrams: 1.5 },
      { name: 'olive oil', quantity: '1 tbsp olive oil (absorbed into patties)', section: 'falafel', ndbNo: '4053', portionDesc: 'g', portionGrams: 12.0 },
      { name: 'pita bread, white', quantity: '1 pita (60g)', section: 'assembly', ndbNo: '18413', portionDesc: 'g', portionGrams: 60.0 },
      { name: 'tomato', quantity: '1 small, sliced (50g)', section: 'assembly', ndbNo: '11529', portionDesc: 'g', portionGrams: 50.0 },
      { name: 'red onion', quantity: '¼ small red onion, thinly sliced (20g)', section: 'assembly', ndbNo: '11282', portionDesc: 'g', portionGrams: 20.0 },
      { name: 'tahini', quantity: '4 tsp', section: 'assembly', ndbNo: '12166', portionDesc: 'g', portionGrams: 20.0 },
      { name: 'Greek whole milk yogurt', quantity: '2 tbsp', section: 'assembly', ndbNo: '1293', portionDesc: 'g', portionGrams: 30.0 },
      { name: 'fresh dill', quantity: '1 tsp chopped', section: 'assembly', ndbNo: '2045', portionDesc: 'g', portionGrams: 0.7 },
      { name: 'fresh parsley', quantity: '1 tsp chopped', section: 'assembly', ndbNo: '11297', portionDesc: 'g', portionGrams: 1.3 },
      { name: 'fresh mint', quantity: '1 tsp chopped', section: 'assembly', ndbNo: '2065', portionDesc: 'g', portionGrams: 0.7 },
      { name: 'lemon juice', quantity: '½ tsp', section: 'assembly', ndbNo: '9152', portionDesc: 'g', portionGrams: 2.5 },
      { name: 'salt', quantity: 'pinch (0.3g)', section: 'assembly', ndbNo: '2047', portionDesc: 'g', portionGrams: 0.3 }
