    recipeIngredients: [
      { name: 'Smashed Potatoes', quantity: 'custom (g)', foodWord: 'SMASHEDPOTATOES', portionDesc: 'custom (g)', portionGrams: 100.0, isDish: true },
      { name: 'potato', quantity: '12 small potatoes (1,104g)', section: 'potatoes', ndbNo: '11354', portionDesc: 'g', portionGrams: 1104.0 },
      { name: 'olive oil', quantity: '3 tbsp', section: 'smash', ndbNo: '4053', portionDesc: 'g', portionGrams: 40.5 },
      { name: 'fresh rosemary', quantity: '2 tbsp fresh rosemary, finely chopped', section: 'smash', ndbNo: '2063', portionDesc: 'g', portionGrams: 3.4 },
      { name: 'garlic powder', quantity: '1 tsp', section: 'smash', ndbNo: '2020', portionDesc: 'g', portionGrams: 3.1 },
      { name: 'salt', quantity: '1½ tsp', section: 'smash', ndbNo: '2047', portionDesc: 'g', portionGrams: 9.0 },
      { name: 'ground black pepper', quantity: '½ tsp', section: 'smash', ndbNo: '2030', portionDesc: 'g', portionGrams: 1.15 }
    ],
    recipeInstructions: [
      'Preheat oven to 450°F. Put potatoes in a large pot. Cover with cold water generously salted with table salt (½ tbsp per quart of water). Bring to a boil, then gently simmer until just tender when pierced, about 20 minutes. Drain well.',
      'Transfer potatoes to a well-oiled baking sheet. Use the bottom of a glass or measuring cup to firmly smash each potato to about ½-inch thickness.',
      'Drizzle olive oil over the smashed potatoes. Sprinkle with rosemary, garlic powder, salt, and black pepper.',
      'Roast at 450°F for 20 to 25 minutes until edges are crisp and golden.',
      'Serve hot.',
      'Suggestions (not included): Top with vegan sour cream or fresh herbs if desired.'
    ],
