    recipeIngredients: [
      { name: 'Beef Pho', quantity: 'custom (g)', foodWord: 'BEEFPHO', portionDesc: 'custom (g)', portionGrams: 100.0, isDish: true },
      { name: 'Beef Stock', quantity: '8 cups Beef Stock (recipe)', section: 'stock_ref', foodWord: 'BEEFSTOCK', portionDesc: 'g', portionGrams: 1892.0, isDish: true, componentRef: 'STOCK_004' },
      { name: 'onion', quantity: '1 medium onion, halved and charred', section: 'stock', ndbNo: '11282', portionDesc: 'g', portionGrams: 110.0 },
      { name: 'fresh ginger', quantity: '2-inch piece ginger, halved lengthwise', section: 'stock', ndbNo: '11216', portionDesc: 'g', portionGrams: 20.0 },
      { name: 'fish sauce', quantity: '3 tbsp fish sauce', section: 'stock', ndbNo: '16124', portionDesc: 'g', portionGrams: 45.0 },
      { name: 'star anise', quantity: '3 whole star anise', section: 'stock', ndbNo: '2002', portionDesc: 'g', portionGrams: 3.0 },
      { name: 'cinnamon stick', quantity: '1 cinnamon stick, cracked', section: 'stock', ndbNo: '2010', portionDesc: 'g', portionGrams: 1.5 },
      { name: 'cloves', quantity: '4 whole cloves', section: 'stock', ndbNo: '2011', portionDesc: 'g', portionGrams: 2.0 },
      { name: 'coriander seeds', quantity: '1 tsp coriander seeds', section: 'stock', ndbNo: '2013', portionDesc: 'g', portionGrams: 2.5 },
      { name: 'sugar', quantity: '1 tsp sugar', section: 'stock', ndbNo: '19335', portionDesc: 'g', portionGrams: 4.2 },
      { name: 'rice noodles', quantity: '8 oz dried rice noodles', section: 'noodles', ndbNo: '20133', portionDesc: 'g', portionGrams: 226.8 },
      { name: 'water', quantity: '4 cups', section: 'noodles', ndbNo: '14411', portionDesc: 'g', portionGrams: 946.0 },
      { name: 'beef flank steak', quantity: '3/4 lb beef flank steak, thinly sliced against the grain', section: 'beef', ndbNo: '23656', portionDesc: 'g', portionGrams: 340.2 }
    ],
    recipeInstructions: [
      'In a large pot, combine the beef stock, onion, ginger, fish sauce, star anise, cinnamon stick, cloves, coriander seeds, and sugar. Bring to a boil, reduce heat, and simmer for 20 minutes. Strain through a fine-mesh strainer, discard solids, and return the broth to the pot. Keep at a gentle simmer over low heat.',
      'Soak the rice noodles in cold water for 20 minutes. Bring a separate pot of water to a boil, cook the noodles for 1-2 minutes until just tender, then drain and divide among 4 bowls.',
      'Arrange the raw beef slices over the noodles in each bowl.',
      'Ladle the simmering hot broth over the beef and noodles. The heat of the broth will cook the beef to medium-rare. Serve immediately.',
      'Suggestions (not included): Serve with bean sprouts, fresh Thai basil, lime wedges, hoisin sauce, and sriracha.'
    ],
